/// 浮窗与两页共用设置控件的文字。按语言取实现。
pub fn overlay(language: AppLanguage) -> &'static dyn OverlayStrings {
    match language {
        AppLanguage::En => &OverlayStringsEn,
        AppLanguage::Zh => &OverlayStringsZh,
        AppLanguage::Ru => &OverlayStringsRu,
        AppLanguage::Ja => &OverlayStringsJa,
        AppLanguage::Ko => &OverlayStringsKo,
        AppLanguage::Fr => &OverlayStringsFr,
        AppLanguage::De => &OverlayStringsDe,
        AppLanguage::Es => &OverlayStringsEs,
    }
}
